// Concrete C# types for generated local variables.
//
// ast-transpiler's C# printer declares every initialised local as `object` unless its own
// getCSharpLocalType() can prove a type. This module wraps printVariableDeclarationList (and
// related printer hooks) on the C# printer instance and names a type only where the C# runtime
// value ALREADY is that type: the hand-written C# signature of the callee (the tables below),
// every return path of a same-file definition, or the join of the initialiser and every later
// write along box-identical edges. Anything unprovable keeps `object`. Everything is proven from
// the C# side, never from the TypeScript annotation alone.
//
// IMPORTANT: scan the AST with `declaration.name.text`, print with
// `printNode(declaration.name)` — ReservedKeywordsReplacements renames `type` -> `typeVar`,
// `params` -> `parameters`, so a printed-name scan silently matches nothing.

import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { csharpStructReturns } from './csharp-struct-returns.js';
import * as astTranspilerUtils from 'ast-transpiler/tsUtils';

// ts/src index scans read real sources plus this process's own stripped base copy; sibling transpilers
// create and delete their temp copies (`*.nooverloads.<pid>.ts`, `.__ExchangeNoOverloads*.ts`) meanwhile
export function isTsIndexSource (name) {
    const temp = /\.nooverloads\.(\d+)\.ts$/.exec (name);
    return name.endsWith ('.ts') && !name.endsWith ('.d.ts') && !name.startsWith ('.') && (temp === null || temp[1] === String (process.pid));
}

// a file gone between listing and reading is skipped; any other failure ends the transpile
export function readTsIndexSource (file) {
    try {
        return fs.readFileSync (file, 'utf8');
    } catch (e) {
        if (e?.code === 'ENOENT') {
            return undefined;
        }
        console.error ('[local-types] ts/src index scan failed on ' + file + ': ' + (e?.stack ?? e));
        process.exit (1);
    }
}

// The generator hands TS7 nodes/checker objects to these hooks: read enums, guards and parsing
// from the same typescript package ast-transpiler resolves, plus its TS6-named helpers.
const generatorRequire = createRequire (createRequire (import.meta.url).resolve ('ast-transpiler'));
const tsAst = generatorRequire ('typescript/unstable/ast');
const tsIs = generatorRequire ('typescript/unstable/ast/is');
const tsSync = generatorRequire ('typescript/unstable/sync');
let tsApi;
export const ts = {
    ...tsAst, ...tsIs, ...tsSync, ...astTranspilerUtils,
    // standalone parse (no program) over the generator's API process
    createSourceFile: (fileName, text) => (tsApi ??= new tsSync.API ({ cwd: process.cwd () })).createSourceFile (fileName, text),
};
